@import "@fontsource-variable/host-grotesk";
@import "@fontsource/dm-mono/400.css";

/* Light (faithful): pure white sections, black ink with a 50% step, warm off-white #f7f7f5
   cards and footer, #000 for the bands (those are .dark scopes in the blocks). No brand colour
   in the chrome: glow (warm engine orange) and highlight (cool blue) only light up the
   CTA on hover. */
:root {
  --background: #ffffff;
  --foreground: #000000;
  --card: #f7f7f5;
  --card-foreground: #000000;
  --popover: #ffffff;
  --popover-foreground: #000000;
  --primary: #000000;
  --primary-foreground: #ffffff;
  --secondary: #f7f7f5;
  --secondary-foreground: #000000;
  --muted: #ebebe7;
  --muted-foreground: rgb(0 0 0 / 50%);
  --accent: #f3f4f6;
  --accent-foreground: #000000;
  --destructive: #d92d20;
  --destructive-foreground: #ffffff;
  --border: rgb(0 0 0 / 12%);
  --input: rgb(0 0 0 / 18%);
  --ring: #000000;
  --highlight: #5b7cff;
  --highlight-foreground: #ffffff;
  --glow: #ff8a3d;
  --chart-1: #000000;
  --chart-2: #ff8a3d;
  --chart-3: #5b7cff;
  --chart-4: #8a8a85;
  --chart-5: #c9c9c3;
  --sidebar: #f7f7f5;
  --sidebar-foreground: #000000;
  --sidebar-primary: #000000;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #ebebe7;
  --sidebar-accent-foreground: #000000;
  --sidebar-border: rgb(0 0 0 / 12%);
  --sidebar-ring: #000000;

  --typeface-body: "Host Grotesk Variable", "Helvetica Neue", Arial, sans-serif;
  --typeface-display: "Host Grotesk Variable", "Helvetica Neue", Arial, sans-serif;
  --typeface-mono: "DM Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 1rem;
  --page-width: 90rem;
  /* phones put text 32px from the edge; at 1440 this gives the original's ~457px cards */
  --page-gutter: 2rem;
  --section-y: 6rem;
}

/* Dark: the original's black bands as a whole page. White ink with the 50% step, white/15
   hairlines, #111 cards and footer, white pills with black text. */
.dark {
  --background: #000000;
  --foreground: #ffffff;
  --card: #111111;
  --card-foreground: #ffffff;
  --popover: #111111;
  --popover-foreground: #ffffff;
  --primary: #ffffff;
  --primary-foreground: #000000;
  --secondary: #0c0c0c;
  --secondary-foreground: #ffffff;
  --muted: #1c1c1c;
  --muted-foreground: rgb(255 255 255 / 50%);
  --accent: rgb(255 255 255 / 10%);
  --accent-foreground: #ffffff;
  --destructive: #f0584c;
  --destructive-foreground: #ffffff;
  --border: rgb(255 255 255 / 15%);
  --input: rgb(255 255 255 / 20%);
  --ring: #ffffff;
  --highlight: #7d97ff;
  --highlight-foreground: #000000;
  --glow: #ff9a55;
  --chart-1: #ffffff;
  --chart-2: #ff9a55;
  --chart-3: #7d97ff;
  --chart-4: #8a8a85;
  --chart-5: #4a4a46;
  --sidebar: #0c0c0c;
  --sidebar-foreground: #ffffff;
  --sidebar-primary: #ffffff;
  --sidebar-primary-foreground: #000000;
  --sidebar-accent: #1c1c1c;
  --sidebar-accent-foreground: #ffffff;
  --sidebar-border: rgb(255 255 255 / 15%);
  --sidebar-ring: #ffffff;
}
